import itertools

n = 13

def autocorr(seq, k):
    n = len(seq)
    return sum(seq[i] * seq[i+k] for i in range(n-k))

# Let's try all combinations of interpretations
# seq indexing: 0-indexed or 1-indexed
# c indexing: 0-indexed or 1-indexed

interpretations = []

for seq_idx_type in [0, 1]:  # 0 = 0-indexed, 1 = 1-indexed
    for c_idx_type in [0, 1]:  # 0 = 0-indexed, 1 = 1-indexed
        count = 0
        solutions = []
        for bits in itertools.product([-1, 1], repeat=n):
            seq = list(bits)

            # Check seq constraints
            if seq_idx_type == 0:
                # 0-indexed: seq[8]=1, seq[10]=-1
                if seq[8] != 1 or seq[10] != -1:
                    continue
            else:
                # 1-indexed: seq[8]=1 means seq[7]=1, seq[10]=-1 means seq[9]=-1
                if seq[7] != 1 or seq[9] != -1:
                    continue

            c = [autocorr(seq, k) for k in range(1, n)]

            # Check c constraints
            if c_idx_type == 0:
                # 0-indexed: c[4]=2, c[5]=-1 means lag 5 and lag 6
                if c[4] != 2 or c[5] != -1:
                    continue
            else:
                # 1-indexed: c[4]=2 means lag 4 (index 3), c[5]=-1 means lag 5 (index 4)
                if c[3] != 2 or c[4] != -1:
                    continue

            sum_sq = sum(v*v for v in c)
            if sum_sq <= 28:
                solutions.append(seq)
                count += 1

        interpretations.append({
            'seq_idx': seq_idx_type,
            'c_idx': c_idx_type,
            'count': count,
            'solutions': solutions[:3] if solutions else []
        })
        print(f"seq_idx={'0-idx' if seq_idx_type==0 else '1-idx'}, c_idx={'0-idx' if c_idx_type==0 else '1-idx'}: count={count}")
        if count > 0:
            print(f"  First solution: {solutions[0]}")
            c = [autocorr(solutions[0], k) for k in range(1, n)]
            print(f"  c = {c}")
            print(f"  sum_sq = {sum(v*v for v in c)}")

print("\n\nSummary:")
for interp in interpretations:
    print(f"seq_{interp['seq_idx']}, c_{interp['c_idx']}: {interp['count']} solutions")
